// Interactive version of the Weather Trends report.
// Data comes from data.js (window.WEATHER), generated by scripts/build_dataset.py.

const D = window.WEATHER;
const SVG_NS = "http://www.w3.org/2000/svg";
const BASE_START = 1854;
const BASE_END = 1900;
const MAIN_SERIES = ["Global", "Campinas", "Amsterdam", "Dublin"];
const CLASS = { Global: "global", Campinas: "campinas", Amsterdam: "amsterdam", Dublin: "dublin" };
const LABEL = { Global: "Global (land)" };

// ---------- helpers ----------

function svg(tag, attrs = {}, parent) {
  const node = document.createElementNS(SVG_NS, tag);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  if (parent) parent.appendChild(node);
  return node;
}

function html(tag, attrs = {}, text) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  if (text !== undefined) node.textContent = text;
  return node;
}

const fmt = (v, digits = 1) => v.toFixed(digits).replace("-", "−");
const fmtSigned = (v, digits = 1) => (v > 0 ? "+" : "") + fmt(v, digits);

// Year -> temperature, for one series.
function yearMap(name) {
  const s = D.series[name];
  return new Map(s.years.map((y, i) => [y, s.temps[i]]));
}

function baseline(map) {
  let sum = 0, n = 0;
  for (let y = BASE_START; y <= BASE_END; y++) if (map.has(y)) { sum += map.get(y); n++; }
  return sum / n;
}

function periodMean(map, start, end) {
  let sum = 0, n = 0;
  for (let y = start; y <= end; y++) if (map.has(y)) { sum += map.get(y); n++; }
  return sum / n;
}

// Trailing moving average: a year gets a value only when all `window` years exist,
// so a gap in the data never turns into a misleading average.
function movingAverage(map, window, start) {
  const years = [...map.keys()].filter((y) => y >= start).sort((a, b) => a - b);
  const out = [];
  for (const y of years) {
    let sum = 0, ok = true;
    for (let k = 0; k < window; k++) {
      if (!map.has(y - k) || y - k < start) { ok = false; break; }
      sum += map.get(y - k);
    }
    if (ok) out.push([y, sum / window]);
  }
  return out;
}

function niceTicks(min, max, count) {
  const span = max - min;
  const step0 = span / count;
  const mag = Math.pow(10, Math.floor(Math.log10(step0)));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => span / s <= count) || 10 * mag;
  const ticks = [];
  for (let t = Math.ceil(min / step) * step; t <= max + 1e-9; t += step) ticks.push(+t.toFixed(10));
  return { ticks, step };
}

// ---------- tooltip ----------

const tooltip = document.getElementById("tooltip");

function showTooltip(title, rows, x, y) {
  tooltip.replaceChildren();
  tooltip.appendChild(html("div", { class: "t-titulo" }, title));
  for (const r of rows) {
    const line = html("div", { class: "t-linha" });
    if (r.cls) line.appendChild(html("span", { class: `chave ${r.cls}` }));
    line.appendChild(html("strong", {}, r.value));
    line.appendChild(html("span", {}, r.label));
    tooltip.appendChild(line);
  }
  tooltip.hidden = false;
  const box = tooltip.getBoundingClientRect();
  let left = x + 16;
  if (left + box.width > window.innerWidth - 8) left = x - box.width - 16;
  let top = y - box.height / 2;
  top = Math.max(8, Math.min(top, window.innerHeight - box.height - 8));
  tooltip.style.left = `${Math.max(8, left)}px`;
  tooltip.style.top = `${top}px`;
}

function hideTooltip() { tooltip.hidden = true; }

// The tooltip is fixed on screen, so a tooltip opened by a button closes when the page scrolls.
let activeHide = null;
window.addEventListener("scroll", () => { if (activeHide) { activeHide(); activeHide = null; } }, { passive: true });

// ---------- line chart ----------

// series: [{ name, label, cls, points: [[year, value]], endLabel, muted }]
function lineChart(container, { series, unit, zeroLine, xMin, xMax }) {
  container.replaceChildren();
  const width = Math.max(320, container.clientWidth - 8);
  const narrow = width < 560;
  const height = narrow ? 300 : 380;
  const m = { top: 16, right: narrow ? 16 : 150, bottom: 28, left: 44 };
  const w = width - m.left - m.right;
  const h = height - m.top - m.bottom;

  const all = series.flatMap((s) => s.points.map((p) => p[1]));
  let yMin = Math.min(...all), yMax = Math.max(...all);
  if (zeroLine) { yMin = Math.min(yMin, 0); yMax = Math.max(yMax, 0); }
  const pad = (yMax - yMin) * 0.06;
  const { ticks: yTicks } = niceTicks(yMin - pad, yMax + pad, narrow ? 5 : 6);
  yMin = Math.min(yMin - pad, yTicks[0]);
  yMax = Math.max(yMax + pad, yTicks[yTicks.length - 1]);

  const x = (yr) => m.left + ((yr - xMin) / (xMax - xMin)) * w;
  const y = (v) => m.top + (1 - (v - yMin) / (yMax - yMin)) * h;

  const root = svg("svg", { viewBox: `0 0 ${width} ${height}`, role: "img", "aria-label": container.dataset.label || "Line chart" }, container);

  for (const t of yTicks) {
    svg("line", { class: "grade-linha", x1: m.left, x2: m.left + w, y1: y(t), y2: y(t) }, root);
    svg("text", { class: "eixo-texto", x: m.left - 8, y: y(t) + 4, "text-anchor": "end" }, root).textContent = fmt(t, Number.isInteger(t) ? 0 : 1);
  }
  if (zeroLine) svg("line", { class: "linha-zero", x1: m.left, x2: m.left + w, y1: y(0), y2: y(0) }, root);
  const xStep = narrow ? 50 : 25;
  for (let t = Math.ceil(xMin / xStep) * xStep; t <= xMax; t += xStep) {
    svg("text", { class: "eixo-texto", x: x(t), y: height - 8, "text-anchor": "middle" }, root).textContent = t;
  }
  svg("text", { class: "eixo-texto", x: m.left - 8, y: m.top - 4, "text-anchor": "end" }, root).textContent = unit;

  // Muted series first, so the highlighted ones sit on top.
  const ordered = [...series].sort((a, b) => (b.muted ? 1 : 0) - (a.muted ? 1 : 0));
  for (const s of ordered) {
    if (!s.points.length) continue;
    // Break the line where years are missing.
    let d = "", prev = null;
    for (const [yr, v] of s.points) {
      d += `${prev !== null && yr - prev === 1 ? "L" : "M"}${x(yr).toFixed(1)},${y(v).toFixed(1)}`;
      prev = yr;
    }
    svg("path", { class: `serie ${s.cls}`, d }, root);
  }

  // End labels on wide screens, pushed apart when they would overlap, with a leader line.
  if (!narrow) {
    const labels = series.filter((s) => s.endLabel && s.points.length).map((s) => {
      const [yr, v] = s.points[s.points.length - 1];
      return { s, yr, v, py: y(v), ly: y(v) };
    }).sort((a, b) => a.py - b.py);
    const gap = 15;
    for (let i = 1; i < labels.length; i++) labels[i].ly = Math.max(labels[i].ly, labels[i - 1].ly + gap);
    const overflow = labels.length ? labels[labels.length - 1].ly - (m.top + h) : 0;
    if (overflow > 0) labels.forEach((l) => (l.ly -= overflow));
    const lx = m.left + w + 18;
    for (const l of labels) {
      svg("line", { class: "guia", x1: x(l.yr) + 4, y1: l.py, x2: lx - 4, y2: l.ly }, root);
      const text = svg("text", { class: "rotulo-fim", x: lx, y: l.ly + 4 }, root);
      text.appendChild(document.createTextNode(`${l.s.label} `));
      const val = svg("tspan", { class: "valor" }, text);
      val.textContent = zeroLine ? fmtSigned(l.v, 2) : fmt(l.v, 2);
    }
  }

  // Hover layer: crosshair snaps to the nearest year, the tooltip lists every visible series.
  const hoverGroup = svg("g", {}, root);
  const crosshair = svg("line", { class: "mira", y1: m.top, y2: m.top + h, visibility: "hidden" }, hoverGroup);
  const dotsGroup = svg("g", {}, hoverGroup);
  const overlay = svg("rect", { class: "camada-hover", x: m.left, y: m.top, width: w, height: h, tabindex: 0,
    "aria-label": "Chart values. Use the left and right arrow keys to move between years." }, root);
  const lookup = series.map((s) => ({ s, map: new Map(s.points) }));
  let current = null;

  function show(yr, clientX, clientY) {
    yr = Math.max(xMin, Math.min(xMax, Math.round(yr)));
    current = yr;
    crosshair.setAttribute("x1", x(yr));
    crosshair.setAttribute("x2", x(yr));
    crosshair.setAttribute("visibility", "visible");
    dotsGroup.replaceChildren();
    const rows = [];
    for (const { s, map } of lookup) {
      if (!map.has(yr)) continue;
      const v = map.get(yr);
      if (!s.muted) {
        svg("circle", { class: `ponto ${s.cls}`, cx: x(yr), cy: y(v), r: 4.5 }, dotsGroup);
        rows.push({ cls: s.cls, value: `${zeroLine ? fmtSigned(v, 2) : fmt(v, 2)} °C`, label: s.label, v });
      }
    }
    rows.sort((a, b) => b.v - a.v);
    if (!rows.length) rows.push({ value: "No data", label: "" });
    const box = root.getBoundingClientRect();
    const cx = clientX ?? box.left + (x(yr) / width) * box.width;
    const cy = clientY ?? box.top + box.height / 2;
    showTooltip(String(yr), rows, cx, cy);
  }

  function hide() {
    crosshair.setAttribute("visibility", "hidden");
    dotsGroup.replaceChildren();
    hideTooltip();
  }

  // Lets the "Show in the chart" buttons point at a year.
  container.showYear = (yr) => { show(yr); activeHide = hide; };

  overlay.addEventListener("pointermove", (e) => {
    const box = root.getBoundingClientRect();
    const px = ((e.clientX - box.left) / box.width) * width;
    show(xMin + ((px - m.left) / w) * (xMax - xMin), e.clientX, e.clientY);
  });
  overlay.addEventListener("pointerleave", hide);
  overlay.addEventListener("blur", hide);
  overlay.addEventListener("focus", () => show(current ?? xMax));
  overlay.addEventListener("keydown", (e) => {
    if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
      e.preventDefault();
      show((current ?? xMax) + (e.key === "ArrowLeft" ? -1 : 1));
    } else if (e.key === "Escape") hide();
  });

  // On narrow screens the end labels are replaced by a legend.
  if (narrow) {
    const legend = html("div", { class: "legenda-grafico" });
    for (const s of series.filter((s) => s.endLabel)) {
      const item = html("span");
      item.appendChild(html("span", { class: `chave ${s.cls}` }));
      item.appendChild(document.createTextNode(s.label));
      legend.appendChild(item);
    }
    container.appendChild(legend);
  }
}

// ---------- 0. tiles ----------

function renderTiles() {
  const box = document.getElementById("tiles");
  for (const name of ["Campinas", "Amsterdam", "Dublin", "Global"]) {
    const map = yearMap(name);
    const change = periodMean(map, 1991, 2020) - baseline(map);
    const tile = html("div", { class: "tile" });
    const label = html("p", { class: "tile-rotulo" });
    label.appendChild(html("span", { class: `chave ${CLASS[name]}` }));
    label.appendChild(document.createTextNode(LABEL[name] || name));
    const value = html("p", { class: "tile-valor" }, fmtSigned(change, 2));
    value.appendChild(html("small", {}, " °C"));
    tile.append(label, value);
    box.appendChild(tile);
  }
}

// ---------- 02. city list ----------

function renderList() {
  const numbers = document.getElementById("list-numbers");
  for (const [value, label] of [[D.cityCount, "rows"], [D.cityNames, "city names"], [D.countryCount, "countries"]]) {
    const card = html("div");
    card.appendChild(html("strong", {}, String(value)));
    card.appendChild(html("span", {}, label));
    numbers.appendChild(card);
  }
  const chips = document.getElementById("duplicates");
  const byCity = {};
  for (const d of D.duplicates) (byCity[d.city] ||= []).push(d.country);
  for (const [city, countries] of Object.entries(byCity)) {
    chips.appendChild(html("li", {}, `${city}: ${countries.join(", ")}`));
  }

  const bars = document.getElementById("continents");
  const max = Math.max(...D.continents.map((c) => c.cities));
  for (const c of D.continents) {
    const row = html("div", { class: "barra" });
    row.appendChild(html("span", {}, c.continent));
    const track = html("div", { class: "barra-trilho" });
    const fill = html("div", { class: "barra-fill", title: `${c.continent}: ${c.cities} cities` });
    fill.style.width = `${(c.cities / max) * 85}%`;
    const value = html("span", { class: "barra-valor" }, String(c.cities));
    value.style.left = `${(c.cities / max) * 85}%`;
    track.append(fill, value);
    row.appendChild(track);
    bars.appendChild(row);
  }
}

// ---------- 03. map ----------

function parseCell(cell) {
  const m = cell.match(/([\d.]+)([NS])-([\d.]+)([EW])/);
  return { lat: (m[2] === "S" ? -1 : 1) * +m[1], lon: (m[4] === "W" ? -1 : 1) * +m[3] };
}

function renderMap() {
  const box = document.getElementById("map");
  const M = D.brazilMap;
  const proj = (lon, lat) => [(lon - M.lon0) * M.kx * M.scale, (M.lat1 - lat) * M.scale];
  const root = svg("svg", { viewBox: `0 0 ${M.width} ${M.height}`, role: "img", "aria-label": "Map of Brazil with the 11 cities in the database" }, box);
  svg("path", { class: "pais", d: M.path }, root);

  const grid = svg("g", { class: "grade-camada" }, root);
  const cells = new Map();
  for (const c of D.brazil) {
    const g = parseCell(c.cell);
    const [gx, gy] = proj(g.lon, g.lat);
    const [cx, cy] = proj(c.longitude, c.latitude);
    svg("line", { class: "ligacao", x1: cx, y1: cy, x2: gx, y2: gy }, grid);
    cells.set(c.cell, [gx, gy]);
  }
  for (const [gx, gy] of cells.values()) svg("rect", { class: "ponto-grade", x: gx - 5, y: gy - 5, width: 10, height: 10 }, grid);

  // Labels placed by hand where cities are close to each other.
  const offsets = { Campinas: [-8, -6, "end"], Guarulhos: [8, 12, "start"], Colombo: [8, 4, "start"], Curitiba: [-8, 12, "end"], "Rio de Janeiro": [8, -2, "start"] };
  for (const c of D.brazil) {
    const [cx, cy] = proj(c.longitude, c.latitude);
    const dot = svg("circle", { class: "cidade", cx, cy, r: 6, tabindex: 0, "aria-label": `${c.city}, ${c.state}` }, root);
    const [dx, dy, anchor] = offsets[c.city] || [9, 4, "start"];
    svg("text", { class: "rotulo-cidade", x: cx + dx, y: cy + dy, "text-anchor": anchor }, root).textContent = c.city;
    const twin = D.brazil.find((o) => o.cell === c.cell && o.city !== c.city);
    const rows = [
      { value: `${fmt(c.avg, 2)} °C`, label: "average" },
      { value: `${fmt(c.min, 2)} °C`, label: "coldest year" },
      { value: `${fmt(c.max, 2)} °C`, label: "hottest year" },
    ];
    if (twin) rows.push({ value: "=", label: `same series as ${twin.city}` });
    const show = (e) => {
      const r = dot.getBoundingClientRect();
      showTooltip(`${c.city} · ${c.state}`, rows, e?.clientX ?? r.right, e?.clientY ?? r.top);
    };
    dot.addEventListener("pointermove", show);
    dot.addEventListener("focus", () => show());
    dot.addEventListener("pointerleave", hideTooltip);
    dot.addEventListener("blur", hideTooltip);
  }

  document.getElementById("show-grid").addEventListener("change", (e) => box.classList.toggle("com-grade", e.target.checked));
}

// ---------- 05. local vs global ----------

const trendState = { mode: "change", window: 4, visible: new Set(MAIN_SERIES) };

function seriesPoints(name, mode, window) {
  const map = yearMap(name);
  let points = movingAverage(map, window, BASE_START);
  if (mode === "change") {
    const base = baseline(map);
    points = points.map(([y, v]) => [y, v - base]);
  }
  return points;
}

function renderTrend() {
  const { mode, window, visible } = trendState;
  const series = MAIN_SERIES.filter((n) => visible.has(n)).map((n) => ({
    name: n, label: LABEL[n] || n, cls: CLASS[n], endLabel: true, points: seriesPoints(n, mode, window),
  }));
  const box = document.getElementById("trend-chart");
  box.dataset.label = mode === "change" ? "Change in temperature since 1854–1900" : "Temperature";
  lineChart(box, { series, unit: "°C", zeroLine: mode === "change", xMin: BASE_START, xMax: 2024 });
  const smooth = window === 1 ? "yearly values" : `${window}-year moving average`;
  let caption = mode === "change"
    ? `Difference from each series' own 1854–1900 average, ${smooth}. Cities end in 2020, the global land average in 2024.`
    : `Yearly average temperature, ${smooth}. Cities end in 2020, the global land average in 2024.`;
  if (window === 30 && mode === "change") caption += " At 2020, each line shows its 1991–2020 average, the number used in the key observations.";
  document.getElementById("trend-caption").textContent = caption;
  renderTrendTable();
}

// Applies a chart setting from a "Show in the chart" button and points at a year.
const trendUI = { modeButtons: [], slider: null, out: null, toggles: {} };

function setTrend({ mode, window: win, series, year }) {
  trendState.mode = mode;
  trendState.window = win;
  trendState.visible = new Set(series);
  trendUI.modeButtons.forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.mode === mode)));
  trendUI.slider.value = String(win);
  trendUI.out.textContent = win === 1 ? "off" : `${win} years`;
  for (const [n, b] of Object.entries(trendUI.toggles)) b.setAttribute("aria-pressed", String(trendState.visible.has(n)));
  renderTrend();

  // Point at the year once the page has scrolled to the chart.
  const box = document.getElementById("trend-chart");
  let done = false;
  const point = () => { if (done) return; done = true; box.showYear(year); };
  window.addEventListener("scrollend", point, { once: true });
  setTimeout(point, 1500);
  box.scrollIntoView({ behavior: "smooth", block: "center" });
}

function setupShowButtons() {
  document.querySelectorAll("[data-show]").forEach((b) => {
    b.addEventListener("click", () => setTrend(JSON.parse(b.dataset.show)));
  });
}

function renderTrendTable() {
  const { mode } = trendState;
  const names = MAIN_SERIES;
  const table = html("table");
  const head = table.createTHead().insertRow();
  head.appendChild(html("th", {}, "Decade"));
  for (const n of names) head.appendChild(html("th", {}, LABEL[n] || n));
  const body = table.createTBody();
  const maps = Object.fromEntries(names.map((n) => [n, yearMap(n)]));
  const bases = Object.fromEntries(names.map((n) => [n, baseline(maps[n])]));
  // Only full decades with data for every series: the cities end in 2020, so the 2020s would be a single year.
  for (let d = 1970; d <= 2010; d += 10) {
    const row = body.insertRow();
    row.appendChild(html("td", {}, `${d}–${d + 9}`));
    for (const n of names) {
      const v = periodMean(maps[n], d, d + 9);
      const cell = html("td");
      cell.textContent = Number.isNaN(v) ? "–" : mode === "change" ? fmtSigned(v - bases[n], 2) : fmt(v, 2);
      row.appendChild(cell);
    }
  }
  const caption = html("caption", { class: "legenda" }, mode === "change" ? "Average change per decade, °C" : "Average temperature per decade, °C");
  table.prepend(caption);
  const g = maps.Global;
  const recent = mode === "change" ? `${fmtSigned(periodMean(g, 2020, 2024) - bases.Global, 2)} °C` : `${fmt(periodMean(g, 2020, 2024), 2)} °C`;
  const note = html("p", { class: "legenda" },
    `Last five full decades. The 2020s are left out because the cities end in 2020; for the global land average, 2020–2024 averaged ${recent}.`);
  document.getElementById("trend-table").replaceChildren(table, note);
}

function setupTrendControls() {
  const buttons = document.querySelectorAll("#trend-controls [data-mode]");
  trendUI.modeButtons = [...buttons];
  buttons.forEach((b) => b.addEventListener("click", () => {
    trendState.mode = b.dataset.mode;
    buttons.forEach((o) => o.setAttribute("aria-pressed", String(o === b)));
    renderTrend();
  }));
  const slider = document.getElementById("window");
  const out = document.getElementById("window-out");
  trendUI.slider = slider;
  trendUI.out = out;
  slider.addEventListener("input", () => {
    trendState.window = +slider.value;
    out.textContent = slider.value === "1" ? "off" : `${slider.value} years`;
    renderTrend();
  });
  const toggles = document.getElementById("series-toggle");
  for (const n of MAIN_SERIES) {
    const b = html("button", { type: "button", "aria-pressed": "true" });
    b.appendChild(html("span", { class: `chave ${CLASS[n]}` }));
    b.appendChild(document.createTextNode(LABEL[n] || n));
    b.addEventListener("click", () => {
      const on = trendState.visible.has(n);
      if (on && trendState.visible.size === 1) return; // keep at least one line
      on ? trendState.visible.delete(n) : trendState.visible.add(n);
      b.setAttribute("aria-pressed", String(!on));
      renderTrend();
    });
    trendUI.toggles[n] = b;
    toggles.appendChild(b);
  }
}

// ---------- 06. Brazilian cities ----------

function renderBrazil() {
  const select = document.getElementById("city-select");
  const chosen = select.value;
  const others = D.brazil.map((c) => c.city).filter((c) => c !== chosen);
  const series = [
    ...others.map((n) => ({ name: n, label: n, cls: "outras", muted: true, points: seriesPoints(n, "change", 10) })),
    { name: "Global", label: "Global (land)", cls: "global", endLabel: true, points: seriesPoints("Global", "change", 10) },
    { name: chosen, label: chosen, cls: "escolhida", endLabel: true, points: seriesPoints(chosen, "change", 10) },
  ];
  const box = document.getElementById("brazil-chart");
  box.dataset.label = `Change in temperature since 1854–1900, ${chosen}`;
  lineChart(box, { series, unit: "°C", zeroLine: true, xMin: BASE_START, xMax: 2024 });

  const info = D.brazil.find((c) => c.city === chosen);
  const twin = D.brazil.find((c) => c.cell === info.cell && c.city !== chosen);
  const map = yearMap(chosen);
  const change = periodMean(map, 1991, 2020) - baseline(map);
  let text = `${chosen} was ${fmt(change, 2)} °C warmer in 1991–2020 than in 1854–1900. 10-year moving average; gray lines are the other Brazilian cities.`;
  if (twin) text += ` Same series as ${twin.city} (shared grid point).`;
  document.getElementById("brazil-caption").textContent = text;
}

function setupBrazil() {
  const select = document.getElementById("city-select");
  for (const c of D.brazil) select.appendChild(html("option", { value: c.city }, c.city));
  select.value = "Campinas";
  select.addEventListener("change", renderBrazil);
}

// ---------- theme and start ----------

document.querySelector(".tema").addEventListener("click", () => {
  const root = document.documentElement;
  const dark = root.dataset.theme ? root.dataset.theme === "dark" : matchMedia("(prefers-color-scheme: dark)").matches;
  root.dataset.theme = dark ? "light" : "dark";
  try { localStorage.setItem("theme", root.dataset.theme); } catch (e) {}
});

renderTiles();
renderList();
renderMap();
setupTrendControls();
setupBrazil();
setupShowButtons();
renderTrend();
renderBrazil();

let resizeTimer;
let lastWidth = window.innerWidth;
window.addEventListener("resize", () => {
  if (window.innerWidth === lastWidth) return;
  lastWidth = window.innerWidth;
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(() => { renderTrend(); renderBrazil(); }, 150);
});
